<?php
declare(strict_types=1);
require __DIR__.'/gallery-facets.php';
use Namira\{PublicSearch,GalleryFacets,Db,DataBackup,Archive,CleanUrls,Upload};
try{
$start=$checks;
$f=PublicSearch::input($db,[]);ok($f===[],'basic empty search does not silently require known birth place');
ok(GalleryFacets::count($db,$f)===3,'unknown birth places do not remove published images by default');
$o=PublicSearch::basicOptions($db,$f);ok(array_column($o['chips'],'key')===array_keys(PublicSearch::BASIC),'basic filter schema is exactly five ordered chips');
ok(ids($o['geo']['country'])===[$a['country_id']],'basic countries come only from published birth facts');
$f=PublicSearch::input($db,['geo_country'=>(string)$a['country_id']]);ok($f['geo_role']==='birth_place'&&GalleryFacets::count($db,$f)===2,'basic geography is always birth place');
$f=PublicSearch::input($db,['geo_country'=>(string)$b['country_id']]);ok(GalleryFacets::count($db,$f)===0,'martyrdom country never satisfies birth country');
$geo=['geo_country'=>(string)$a['country_id'],'geo_province'=>(string)$a['province_or_state_id'],'geo_county'=>(string)$a['county_id'],'geo_city'=>(string)$a['city_or_village_id']];
$r=PublicSearch::basicResponse($db,$geo+['changed'=>'geo_country']);ok(count($r['cleared'])===3&&!isset($r['filters']['geo_city']),'changing parent clears every descendant including still-valid choices');
$r=PublicSearch::basicResponse($db,array_replace($geo,['geo_country'=>''])+['changed'=>'geo_country']);ok(!isset($r['filters']['geo_role'])&&$r['count']===3,'clearing final geographic parent restores unknown-birth records too');
ok(PublicSearch::advancedRequired(['axis'=>['occupation'=>[$teacher]]]),'old specialist search links are recognized for advanced routing');
ok(!PublicSearch::advancedRequired(['axis'=>['collection'=>[$topic]]]+$geo),'ordinary topic and birth filters stay on simple pages');
$f=PublicSearch::input($db,['axis'=>['collection'=>[$topic]]]+$geo);
foreach([false,true] as $people){$u=PublicSearch::advancedLink($f,$people);parse_str(parse_url($u,PHP_URL_QUERY),$q);ok($q['results']===($people?'martyrs':'images')&&$q['axis']['collection'][0]==$topic,'advanced link preserves nested filters and correct result mode');$advanced=PublicSearch::input($db,$q,true);ok($advanced['places']['birth_place']['city']==$a['city_or_village_id'],'advanced input translates birthplace selections without changing meaning');}
$advanced=PublicSearch::input($db,['places'=>['birth_place'=>['country'=>$a['country_id']],'martyrdom_place'=>['country'=>$b['country_id']]]],true);
ok(GalleryFacets::count($db,$advanced)===2,'independent geographic roles combine on the same related person');
$cross=PublicSearch::input($db,['axis'=>['occupation'=>[$worker]],'places'=>['birth_place'=>['country'=>$a['country_id']]]],true);ok(GalleryFacets::count($db,$cross)===0,'shared image cannot combine occupation from one person with birth place from another');
$partial=person('facet_partial',$teacher,['birth_place'=>$b]);Db::query($db,'UPDATE martyr_public_facts SET province_id=NULL,county_id=NULL WHERE martyr_id=? AND fact_key=?',[$partial,'birth_place']);
$partialImage=photo($partial,120);
$partialFilter=PublicSearch::input($db,['geo_country'=>$b['country_id']]);$o=PublicSearch::basicOptions($db,$partialFilter);
ok($o['geo']['province']===[]&&ids($o['geo']['city'])===[$b['city_or_village_id']],'missing province or county can be skipped without guessing parent data');
foreach([['birth_date',1360],['martyrdom_date',1400]] as [$key,$year])Db::insert($db,'martyr_public_facts',['martyr_id'=>$personA,'fact_key'=>$key,'ordinal'=>0,'year'=>$year,'calendar'=>'jalali','revision'=>1]);
$f=PublicSearch::input($db,['dates'=>['birth_date'=>['calendar'=>'jalali','from'=>'1359','to'=>'1361'],'martyrdom_date'=>['calendar'=>'jalali','from'=>'1399','to'=>'1401']]],true);
ok(GalleryFacets::count($db,$f)===2,'birth and martyrdom year ranges combine against public facts');
$f['dates']['birth_date']['from']='1361';ok(GalleryFacets::count($db,$f)===0,'combined date range excludes a nonmatching birth year');
$photoA=photo($personA,155,[],'photo');Db::query($db,'UPDATE images SET mime=? WHERE id=?',['image/png',$photoA]);
$f=PublicSearch::input($db,['kind'=>'photo','mime'=>'image/png'],true);
ok(GalleryFacets::count($db,$f,true)===1&&GalleryFacets::count($db,$f)===1,'media filters are available in both result modes');
$f['mime']='image/jpeg';ok(GalleryFacets::count($db,$f,true)===1,'independent photo-only person matches its own jpeg');
$f['martyr_id']=(string)$personA;ok(GalleryFacets::count($db,$f,true)===0,'person media predicates must match the same image rather than separate images');
$artistService=new Namira\Artists($db,$actor);$artistId=$artistService->save(['display_name'=>'نام عمومی هنرمند']);Db::query($db,'UPDATE artists SET status=?,public_visible=1,public_snapshot=? WHERE id=?',['published',json_encode(['display_name'=>'نام عمومی هنرمند']),$artistId]);
Db::insert($db,'media_public_artists',['image_id'=>$imageA,'artist_id'=>$artistId,'creator_role'=>'designer','credit_name'=>'نام قدیمی','credit_order'=>0]);
Db::insert($db,'media_public_artists',['image_id'=>$shared,'artist_id'=>$artistId,'creator_role'=>'designer','credit_name'=>'نام دیگر','credit_order'=>0]);
$before=DataBackup::counts($db);
$o=PublicSearch::options($db,[]);
ok(in_array('occupation',array_column($o['axes'],'axis_key'),true)&&in_array($custom,array_column($o['axes'],'axis_key'),true),'advanced axes are read dynamically from public central catalog');
ok(!in_array($privateJob,axisOptions($o,'occupation'),true)&&!in_array($draftJob,axisOptions($o,'occupation'),true),'advanced axes exclude hidden persons and draft images');
ok(!isset($o['places']['burial_place'])&&isset($o['places']['birth_place'],$o['places']['martyrdom_place']),'geographic role groups only appear when public data exists');
ok(isset($o['dates']['birth_date'],$o['dates']['martyrdom_date'])&&!isset($o['dates']['identification_date']),'only actually projected public date fields are searchable');
ok(count($o['media']['artist_id']['rows'])===1&&$o['media']['artist_id']['rows'][0]['title']==='نام عمومی هنرمند','artist options deduplicate by id and use approved public profile name');
ok(GalleryFacets::count($db,PublicSearch::input($db,['places'=>['birth_place'=>['present'=>'0']]],true))===GalleryFacets::count($db,[]),'unchecked place-presence filter never excludes records');
denied(fn()=>PublicSearch::input($db,['places'=>['private_home'=>['country'=>'1']]],true),'private geography cannot enter advanced SQL');
denied(fn()=>PublicSearch::input($db,['text_query'=>'secret','text_field'=>'password_hash'],true),'text filter cannot access arbitrary columns');
denied(fn()=>PublicSearch::input($db,['orientation'=>'x OR 1=1'],true),'invalid media orientation cannot enter SQL');
denied(fn()=>PublicSearch::input($db,['dates'=>['birth_date'=>['from'=>'1400','to'=>'1300']]],true),'invalid advanced date range is rejected');
denied(fn()=>PublicSearch::input($db,['axis'=>['occupation'=>[['bad']]]],true),'nested invalid term ids are rejected');
foreach([false,true] as $people){$f=[];$catalogFilters=PublicSearch::basicOptions($db,$f,$people);$result=PublicSearch::listing($db,$f,$people);ob_start();view($people?'martyrs':'gallery',compact('db','f','catalogFilters','result')+['page'=>$people?'martyrs':'gallery']);$html=ob_get_clean();preg_match_all('/data-filter-chip="([^"]+)"/',$html,$match);ok($match[1]===array_keys(PublicSearch::BASIC),'rendered '.($people?'martyrs':'images').' page contains only five filter buttons');ok(str_contains($html,'data-advanced-link')&&!str_contains($html,'name="geo_role"'),'rendered basic page has advanced link and no place-role selector');}
$f=PublicSearch::input($db,['results'=>'martyrs','axis'=>['collection'=>[$topic]]],true);$options=PublicSearch::options($db,$f,true);$result=PublicSearch::listing($db,$f,true);$result['count']=55;$people=true;ob_start();view('advanced-search',compact('db','f','options','result','people'));$html=ob_get_clean();
ok(str_contains($html,'advanced-search')&&str_contains($html,'results=martyrs')&&str_contains($html,'p=2'),'advanced result pagination keeps its own route and result type');
ok(!str_contains($html,'name="geo_role"')&&str_contains($html,'places[birth_place]'),'advanced geography uses explicit independent roles');
$ui=routeProbe(['page'=>'advanced-search-data','results'=>'martyrs','places'=>['birth_place'=>['country'=>$a['country_id']]]]);
ok($ui['status']===200&&$ui['data']['ok']&&$ui['data']['count']===1&&isset($ui['data']['fieldsHtml']),'advanced GET endpoint returns real count and dependent controls');
$ui=routeProbe(['page'=>'gallery-data','simple'=>'1','mode'=>'results','geo_country'=>$a['country_id']]);
ok($ui['data']['count']===2&&count($ui['data']['facets']['chips'])===5&&isset($ui['data']['advancedUrl']),'simple AJAX endpoint returns five chips and up-to-date advanced link');
$ui=routeProbe(['page'=>'advanced-search-data','results'=>'private']);ok($ui['status']===422&&!$ui['data']['ok'],'advanced API rejects invalid result modes as JSON');
ok(CleanUrls::resolve('/advanced-search',[])['page']==='advanced-search','direct clean advanced route resolves on refresh');
ok(DataBackup::counts($db)===$before,'all search queries and rendered controls preserve every database table');
ok(hash_file('sha256',Upload::absolute(Db::query($db,'SELECT original_path FROM images WHERE id=?',[$imageA])->fetchColumn()))===$hash,'new searches preserve original file content');
if(getenv('SEARCH_UI_FIXTURE')==='1'&&str_starts_with($dsn,'sqlite:'))file_put_contents(BASE_PATH.'/storage/search-ui-fixture.json',json_encode(['storage'=>$root,'dsn'=>$dsn,'a'=>$a,'b'=>$b,'topic'=>$topic,'teacher'=>$teacher,'worker'=>$worker,'custom'=>$custom],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));
echo "\n".($checks-$start)." public search checks passed on ".$db->getAttribute(PDO::ATTR_DRIVER_NAME).".\n";
}catch(Throwable $e){while(ob_get_level())ob_end_clean();fwrite(STDERR,$e->getMessage()."\n".$e->getTraceAsString()."\n");exit(1);}
